#!/usr/bin/env node
// SLP managed-entry sentinel gate (settings-driven-providers.md §6 Phase 2).
// Lives inside the immutable candidate payload at bin/slp-gate.mjs and is
// exec'd by each hook-family slp-* provider's generated gate launcher:
//
//   slp-<family>-<role>  →  export SLP_FAMILY_BIN=<frozen>; exec <node> bin/slp-gate.mjs <native-args...>
//
// The launcher is the real argv[0] because the host's bare `--version`
// probe runs it with provider env entirely absent — node path and family
// binary must come from generated bytes, not env.
//
// The agent.session_open hook overlays a non-empty SLP_SESSION_OPEN_GRANT onto
// the provider env for managed session opens only. A session spawn that
// reaches this command without the grant — a plugin reload gap, a disabled
// plugin, a stale entry after removal — must fail closed rather than spawn an
// unroled native session. A pure `extends`-only alias cannot do that, so the
// gate is the sentinel; the slp-* provider identity (agent.provider) stays
// unchanged.
//
// The gate distinguishes launches by PASEO_AGENT_ID, which the daemon stamps
// into launchContext.env on real session opens (create/resume/refresh/import)
// and on nothing else. Launches without it are not seats — the host runs the
// same provider binary for capability snapshots and model enumeration outside
// any session, and those must pass so the provider can report ready. Only a
// PASEO_AGENT_ID launch is a session spawn, and only it requires the grant.
//
// One further pass-through: the bare `--version` probe (host availability
// probes run argv + '--version' outside any session open and drop provider
// env entirely — the gate answers through the real family binary in every
// grant state, exactly like the shim's probe path).
import { spawn } from 'node:child_process';
import { isAbsolute } from 'node:path';

// Same list as the installed host's RUNTIME_CONTROL_ENV_KEYS
// (server/server/paseo-env.js), plus NODE_OPTIONS — identical to slp-shim.mjs.
// SLP_SESSION_OPEN_GRANT is also stripped: it has served its purpose at this
// boundary and must never propagate into a nested session's environment.
const STRIPPED_ENV_KEYS = [
  'PASEO_NODE_ENV',
  'PASEO_DESKTOP_MANAGED',
  'PASEO_SUPERVISED',
  'ELECTRON_RUN_AS_NODE',
  'ELECTRON_NO_ATTACH_CONSOLE',
  'ESBUILD_BINARY_PATH',
  'NODE_OPTIONS',
  'SLP_SESSION_OPEN_GRANT',
  'SLP_OPENCODE_V2_ONLY',
];

const fail = message => {
  console.error(`slp-gate: ${message}`);
  process.exitCode = 1;
};

// Transparent passthrough: inherited stdio, signal forwarding, exit status.
function passthrough(binary, argv) {
  const env = { ...process.env };
  for (const key of STRIPPED_ENV_KEYS) delete env[key];
  const child = spawn(binary, argv, { stdio: 'inherit', env });
  child.on('error', error => fail(`cannot exec ${binary}: ${error.message}`));
  for (const signal of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(signal, () => child.kill(signal));
  child.on('exit', (code, signal) => {
    process.exitCode = code ?? (signal === 'SIGINT' ? 130 : 143);
  });
}

function resolvedBinary() {
  const binary = process.env.SLP_FAMILY_BIN;
  if (typeof binary !== 'string' || !isAbsolute(binary)) {
    fail('SLP_FAMILY_BIN is not a resolved absolute path');
    return null;
  }
  return binary;
}

function main() {
  // Retired native launcher marker is recognized only to refuse execution.
  // Old recorded scripts can be verified, but new managed opens use ACP.
  if (process.env.SLP_OPENCODE_V2_ONLY === '1') {
    return fail('native OpenCode transport is unsupported; rebind to the managed ACP wrapper');
  }
  const args = process.argv.slice(2);
  if (args.length === 1 && args[0] === '--version') {
    const binary = resolvedBinary();
    if (binary === null) return;
    return passthrough(binary, args);
  }
  const binary = resolvedBinary();
  if (binary === null) return;
  // Session spawns are marked by the daemon's own PASEO_AGENT_ID (stamped into
  // launchContext.env for create/resume/refresh/import opens). Non-session
  // launches — capability snapshots, model enumeration — carry no agent id
  // and no role; refusing them would leave the provider permanently unready.
  const sessionSpawn = typeof process.env.PASEO_AGENT_ID === 'string' && process.env.PASEO_AGENT_ID !== '';
  if (!sessionSpawn) return passthrough(binary, args);
  const grant = process.env.SLP_SESSION_OPEN_GRANT;
  if (typeof grant !== 'string' || grant === '') {
    return fail('managed session launched without live SLP hook grant');
  }
  return passthrough(binary, args);
}

main();
